<?php $editing = isset($book['id']); ?><form method="post" action="<?= $editing ? '/books/update' : '/books' ?>" class="content-card form-grid book-form">
<input type="hidden" name="_csrf" value="<?= htmlspecialchars($csrfToken, ENT_QUOTES, 'UTF-8') ?>"><?php if ($editing): ?><input type="hidden" name="id" value="<?= (int) $book['id'] ?>"><?php endif; ?>
<div class="form-columns"><label>Tên sách *<input name="title" value="<?= htmlspecialchars((string) ($book['title'] ?? ''), ENT_QUOTES, 'UTF-8') ?>" required></label><label>ISBN<input name="isbn" value="<?= htmlspecialchars((string) ($book['isbn'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label><label>Tác giả *<input name="author" value="<?= htmlspecialchars((string) ($book['author'] ?? ''), ENT_QUOTES, 'UTF-8') ?>" required></label><label>Nhà xuất bản<input name="publisher" value="<?= htmlspecialchars((string) ($book['publisher'] ?? ''), ENT_QUOTES, 'UTF-8') ?>"></label><label>Danh mục<select name="category_id"><option value="">-- Chưa phân loại --</option><?php foreach ($categories as $category): ?><option value="<?= (int) $category['id'] ?>" <?= (string) ($book['category_id'] ?? '') === (string) $category['id'] ? 'selected' : '' ?>><?= htmlspecialchars($category['name'], ENT_QUOTES, 'UTF-8') ?></option><?php endforeach; ?></select></label><label>Giá bán *<input type="number" min="0" step="1000" name="price" value="<?= htmlspecialchars((string) ($book['price'] ?? '0'), ENT_QUOTES, 'UTF-8') ?>" required></label><label>Số lượng tồn kho *<input type="number" min="0" name="stock_quantity" value="<?= htmlspecialchars((string) ($book['stock_quantity'] ?? '0'), ENT_QUOTES, 'UTF-8') ?>" required></label><label class="checkbox-label"><input type="checkbox" name="is_active" value="1" <?= !isset($book['is_active']) || $book['is_active'] ? 'checked' : '' ?>> Đang kinh doanh</label></div>
<label>Mô tả<textarea name="description" rows="5"><?= htmlspecialchars((string) ($book['description'] ?? ''), ENT_QUOTES, 'UTF-8') ?></textarea></label><div><button class="btn btn-primary" type="submit"><?= $editing ? 'Lưu thay đổi' : 'Thêm sách' ?></button> <a class="btn btn-light" href="/books">Hủy</a></div></form>
